#include "bits/stdc++.h"using namespace std;#define int long long#define double long double int32_t main() {    int n;    cin >> n;    unordered_map<string, string> m;    for (int i = 0; i < n; i++) {        string key, value;        bool done = false;        cin >> key >> value;        for(auto x : m){            if(key == x.second){                m[x.first] = value;                done = true;            }        }        if(!done){            m[key] = value;        }    }     cout << m.size() << "\n";    for(auto x : m){        cout << x.first << " " << x.second << "\n";    }    return 0;}